const supportKey=(value:string)=>String(value||"").replace(/^\/en(?=\/)/,"").replace(/\?.*$/,"").toLowerCase().replace(/[^a-z0-9가-힣/]+/g,"-");
export function findGeneratedScreenSupport(pageIdOrPath:string){const key=supportKey(pageIdOrPath);return GENERATED_SCREEN_SUPPORT_CATALOG.find(entry=>supportKey(entry.pageId)===key||supportKey(entry.routePath)===key);}
